 const mapPoints=useMemo(()=>[...(trip.latitude!==null&&trip.longitude!==null?[{id:trip.id,name:trip.destination,address:trip.country,latitude:trip.latitude,longitude:trip.longitude,kind:'trip' as const}]:[]),...savedPlaces.filter(p=>p.latitude!==null&&p.longitude!==null).map(p=>({id:p.id,name:p.name,address:p.address,latitude:p.latitude,longitude:p.longitude,kind:'place' as const})),...(focusedPlace?[{id:focusedPlace.placeId||'search',name:focusedPlace.name,address:focusedPlace.address,latitude:focusedPlace.latitude,longitude:focusedPlace.longitude,kind:'search' as const}]:[])],[trip,savedPlaces,focusedPlace]);
