 async function createTrip(e:React.FormEvent){e.preventDefault();if(!destination.trim()||!startDate||!endDate)return;const requestedGroupSize=Number(createGroupSize);if(!Number.isInteger(requestedGroupSize)||requestedGroupSize<1||requestedGroupSize>30){notify('Group size must be between 1 and 30 travelers.');return;}if(endDate<startDate){notify('Your return date must follow your start date.');return;}const d1=new Date(startDate+'T12:00:00'),d2=new Date(endDate+'T12:00:00');const days=Math.max(1,Math.ceil((+d2-+d1)/86400000));let t:Trip={id:createId(),destination:destination.trim(),country:country.trim()||'Destination',dates:`${d1.toLocaleDateString('en',{month:'short',day:'numeric'})} — ${d2.toLocaleDateString('en',{month:'short',day:'numeric',year:'numeric'})}`,from:startDate,to:endDate,cover:'photo-1488646953014-85cb44e25828',days,budget:Number(tripBudget)||2500,spent:0,tag:createStyle.toUpperCase(),currency:tripCurrency,latitude:null,longitude:null,interests:createInterests.split(',').map(x=>x.trim()).filter(Boolean),groupSize:requestedGroupSize};if(supabase&&session){const {data,error}=await supabase.from('trips').insert({owner_id:session.user.id,title:t.destination,destination:t.destination,country:country.trim()||null,starts_on:startDate,ends_on:endDate,budget:t.budget,currency:tripCurrency,travel_style:createStyle,interests:t.interests,group_size:requestedGroupSize}).select('*').single();if(error){notify(`Could not save the trip: ${error.message}`);return;}t=mapCloudTrip(data);}setTrips(p=>[t,...p]);setActive(t.id);setShowModal(false);setDestination('');setCountry('');setTripBudget('2500');setTripCurrency('USD');setPlanningStyle(createStyle);setPlanningInterests(createInterests);setGroupSize(String(requestedGroupSize));setTab('Overview');notify(supabase&&session?'Trip saved to your account.':'Your trip is ready to plan.');}
 async function deleteTrip(id:string){if(!window.confirm('Delete this trip and its itinerary details?'))return;if(supabase&&session){const {error}=await supabase.from('trips').delete().eq('id',id);if(error){notify(`Could not delete the trip: ${error.message}`);return;}}const remaining=trips.filter(t=>t.id!==id);setTrips(remaining);if(active===id)setActive(remaining[0]?.id||'');notify('Trip deleted.');}
 async function addActivity(e:React.FormEvent){e.preventDefault();if(!trip.id||!activityName.trim())return;const day=activityDate||trip.from;if(!day){notify('Add your trip dates before scheduling an activity.');return;}const item:ScheduleItem={id:createId(),tripId:trip.id,date:day,time:activityTime,name:activityName.trim(),detail:activityPlace.trim()||`${trip.destination} · Planned activity`,icon:'✦'};if(editingActivity){item.id=editingActivity;if(supabase&&session){const {error}=await supabase.from('itinerary_items').update({day_date:day,title:item.name,place_name:activityPlace.trim()||null,starts_at:activityTime}).eq('id',editingActivity);if(error){notify(`Could not update activity: ${error.message}`);return;}}setSchedule(s=>s.map(x=>x.id===editingActivity?item:x));notify('Itinerary updated.');}else{if(supabase&&session){const {data,error}=await supabase.from('itinerary_items').insert({trip_id:trip.id,day_date:day,title:item.name,place_name:activityPlace.trim()||null,starts_at:activityTime,sort_order:schedule.filter(x=>x.date===day).length,created_by:session.user.id}).select('*').single();if(error){notify(`Could not save activity: ${error.message}`);return;}item.id=data.id;}setSchedule(s=>[...s,item]);notify('Activity added to your itinerary.');}setActivityName('');setActivityPlace('');setEditingActivity(null);setActivityModal(false);}
 async function deleteActivity(id:string){if(supabase&&session){const {error}=await supabase.from('itinerary_items').delete().eq('id',id);if(error){notify(`Could not remove activity: ${error.message}`);return;}}setSchedule(s=>s.filter(x=>x.id!==id));notify('Activity removed.');}
 function editActivity(item:ScheduleItem){setEditingActivity(item.id);setActivityName(item.name);setActivityPlace(item.detail);setActivityTime(item.time);setActivityDate(item.date);setActivityModal(true);}
 async function addExpense(e:React.FormEvent){e.preventDefault();const amount=Number(expenseAmount);if(!trip.id||!Number.isFinite(amount)||amount<=0){notify('Enter an expense amount greater than zero.');return;}const item:ExpenseItem={id:createId(),tripId:trip.id,amount,currency:expenseCurrency,category:expenseCategory,description:expenseDescription.trim(),date:expenseDate||new Date().toISOString().slice(0,10)};if(supabase&&session){const {data,error}=await supabase.from('expenses').insert({trip_id:trip.id,created_by:session.user.id,amount,currency:item.currency,category:item.category,description:item.description||null,incurred_on:item.date}).select('*').single();if(error){notify(`Could not save expense: ${error.message}`);return;}item.id=data.id;}setExpenses(s=>[item,...s]);setExpenseAmount('');setExpenseDescription('');setExpenseCurrency(trip.currency);setExpenseModal(false);notify('Expense added.');}
 async function deleteExpense(id:string){if(supabase&&session){const {error}=await supabase.from('expenses').delete().eq('id',id);if(error){notify(`Could not delete expense: ${error.message}`);return;}}setExpenses(s=>s.filter(x=>x.id!==id));notify('Expense removed.');}
 async function addPackingItem(e:React.FormEvent){e.preventDefault();if(!trip.id||!packingName.trim())return;let item:PackingItem={id:createId(),tripId:trip.id,name:packingName.trim(),category:packingCategory,packed:false};if(supabase&&session){const {data,error}=await supabase.from('packing_items').insert({trip_id:trip.id,created_by:session.user.id,name:item.name,category:item.category,sort_order:packing.filter(x=>x.category===item.category).length}).select('*').single();if(error){notify(`Could not save packing item: ${error.message}`);return;}item={...item,id:data.id};}setPacking(p=>[...p,item]);setPackingName('');setPackingModal(false);notify('Added to your packing list.');}
