 async function deletePacking(id:string){if(supabase&&session){const {error}=await supabase.from('packing_items').delete().eq('id',id);if(error){notify(`Could not remove item: ${error.message}`);return;}}setPacking(p=>p.filter(x=>x.id!==id));}
 async function searchPlaces(e:React.FormEvent){e.preventDefault();const query=placeQuery.trim();if(query.length<2){setPlaceError('Enter a place or address to search.');return;}setPlaceLoading(true);setPlaceError('');setPlaceResults([]);try{const response=await fetch('/api/places/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Place search is unavailable.');setPlaceResults(data.results||[]);if(!data.results?.length)setPlaceError('No matching places were found. Try adding a city or country.');}catch(error){setPlaceError(error instanceof Error?error.message:'Place search is unavailable.');}finally{setPlaceLoading(false);}}
 async function setTripLocation(place:PlaceResult){setFocusedPlace(place);setMapCenter([place.latitude,place.longitude]);setTrips(current=>current.map(x=>x.id===trip.id?{...x,latitude:place.latitude,longitude:place.longitude}:x));if(supabase&&session){const {error}=await supabase.from('trips').update({destination_latitude:place.latitude,destination_longitude:place.longitude}).eq('id',trip.id);if(error){notify(`Could not save map location: ${error.message}`);return;}}notify('Trip location updated.');}
 async function savePlace(place:PlaceResult){const item:SavedPlace={id:createId(),tripId:trip.id||null,name:place.name,address:place.address,latitude:place.latitude,longitude:place.longitude};if(supabase&&session){const {data,error}=await supabase.from('saved_places').insert({user_id:session.user.id,trip_id:trip.id||null,name:item.name,address:item.address||null,latitude:item.latitude,longitude:item.longitude,source:'Geoapify'}).select('*').single();if(error){notify(`Could not save place: ${error.message}`);return;}item.id=data.id;}setSavedPlaces(items=>[item,...items]);setFocusedPlace(place);setMapCenter([place.latitude,place.longitude]);notify('Place saved.');}
