 async function addReminder(e:React.FormEvent){e.preventDefault();if(!trip.id||!reminderTitle.trim()||!reminderWhen)return;const remindAt=new Date(reminderWhen).toISOString();const item:ReminderItem={id:createId(),tripId:trip.id,title:reminderTitle.trim(),remindAt,completed:false};if(supabase&&session){const {data,error}=await supabase.from('trip_reminders').insert({trip_id:trip.id,user_id:session.user.id,title:item.title,remind_at:remindAt}).select('*').single();if(error){notify(`Could not save reminder: ${error.message}`);return;}setReminders(r=>[...r,{...item,id:data.id}]);}else setReminders(r=>[...r,item]);setReminderTitle('');setReminderModal(false);notify('Reminder set for when Voyara is open.');}
