 async function enableNotifications(){if(!('Notification'in window)){notify('This browser does not support desktop notifications.');return;}const result=await Notification.requestPermission();notify(result==='granted'?'Browser notifications enabled.':'Browser notifications were not enabled.');}
 async function addContact(e:React.FormEvent){e.preventDefault();const name=contactName.trim(),phone=contactPhone.trim();if(!name||phone.length<3){notify('Add a contact name and a valid phone number.');return;}let item:EmergencyContact={id:createId(),name,phone,relationship:contactRelationship.trim(),notes:contactNotes.trim()};if(supabase&&session){const {data,error}=await supabase.from('emergency_contacts').insert({user_id:session.user.id,name,phone,relationship:item.relationship||null,notes:item.notes||null}).select('*').single();if(error){notify(`Could not save contact: ${error.message}`);return;}item={...item,id:data.id};}setContacts(x=>[...x,item]);setContactName('');setContactPhone('');setContactRelationship('');setContactNotes('');setContactModal(false);notify('Emergency contact saved privately.');}
