 async function loadWeather(){setWeatherLoading(true);setWeatherError('');setWeatherData(null);try{const r=await fetch('/api/weather',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({destination:trip.destination,country:trip.country})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Weather is unavailable.');setWeatherData(data);}catch(err){setWeatherError(err instanceof Error?err.message:'Weather is unavailable.');}finally{setWeatherLoading(false);}}
 async function askAssistant(e:React.FormEvent){e.preventDefault();if(!question.trim())return;setLoading(true);setAnswer('');try{const r=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,trip:{destination:trip.destination,country:trip.country,dates:trip.dates,style:trip.tag,budget:trip.budget,currency:trip.currency,interests:trip.interests||[],groupSize:trip.groupSize||Number(groupSize)}})});const data=await r.json();setAnswer(data.answer||data.error||'The assistant is unavailable right now.');}catch{setAnswer('Could not reach the travel assistant. Please try again.');}finally{setLoading(false);}}
 async function saveProfile(event:React.FormEvent){event.preventDefault();const name=profileName.trim();if(!name||name.length>100){setProfileError('Enter a name with 1 to 100 characters.');return;}setProfileSaving(true);setProfileError('');try{if(supabase&&session){const {error:updateError}=await supabase.auth.updateUser({data:{display_name:name}});if(updateError)throw new Error('Could not update your account name.');const {error:profileError}=await supabase.from('profiles').upsert({id:session.user.id,display_name:name,updated_at:new Date().toISOString()});if(profileError)throw new Error('Your auth name changed, but the profile record could not be updated.');}else localStorage.setItem('voyara:profile-name',name);notify('Your profile is up to date.');}catch(error){setProfileError(error instanceof Error?error.message:'Could not save your profile.');}finally{setProfileSaving(false);}}
 async function exportAccountData(){setProfileExporting(true);setProfileExportError('');try{let data:Record<string,unknown>;if(supabase&&session){const tables=['profiles','trips','trip_members','itinerary_items','expenses','packing_items','emergency_contacts','trip_reminders','saved_places','journal_entries','trip_documents'];const results=await Promise.all(tables.map(async table=>{const query=table==='profiles'?supabase.from(table).select('*').eq('id',session.user.id):supabase.from(table).select('*');const {data,error}=await query;if(error)throw new Error(`Could not export ${table}. Apply the latest database migrations and try again.`);return [table,data||[]] as const;}));data={exportedAt:new Date().toISOString(),account:{email:session.user.email,displayName:profileName},records:Object.fromEntries(results)};}else{const records:Record<string,unknown>={trips,schedule,expenses,packing,contacts,reminders,savedPlaces};const journal:Record<string,unknown>={};for(let index=0;index<localStorage.length;index++){const key=localStorage.key(index);if(key?.startsWith('voyara:journal:v1:'))journal[key]=JSON.parse(localStorage.getItem(key)||'[]');}records.journals=journal;data={exportedAt:new Date().toISOString(),account:{displayName:profileName,mode:'demo'},records};}const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=`voyara-data-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(anchor);anchor.click();anchor.remove();URL.revokeObjectURL(url);notify('Your data export is ready.');}catch(error){setProfileExportError(error instanceof Error?error.message:'Could not export your data.');}finally{setProfileExporting(false);}}
 async function draftItinerary(){if(!trip.from||!trip.to){setDraftError('Add start and return dates to this trip first.');return;}setDraftingItinerary(true);setDraftError('');try{const response=await fetch('/api/itinerary/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({destination:trip.destination,country:trip.country,startDate:trip.from,endDate:trip.to,budget:trip.budget,currency:trip.currency,travelStyle:planningStyle,interests:planningInterests.split(',').map(x=>x.trim()).filter(Boolean),groupSize:Number(groupSize)})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not draft this itinerary.');let items:ScheduleItem[]=data.activities.map((activity:{date:string;time:string;title:string;place:string})=>({id:createId(),tripId:trip.id,date:activity.date,time:activity.time,name:activity.title,detail:activity.place||`${trip.destination} · Idea to verify`,icon:'✦'}));if(supabase&&session){const rows=items.map(item=>({trip_id:trip.id,day_date:item.date,title:item.name,place_name:item.detail,starts_at:item.time,sort_order:schedule.filter(existing=>existing.tripId===trip.id&&existing.date===item.date).length,created_by:session.user.id}));const {data:inserted,error}=await supabase.from('itinerary_items').insert(rows).select('*');if(error)throw new Error('Could not save the draft to your account.');items=inserted.map((row:CloudScheduleRow)=>({id:row.id,tripId:trip.id,date:row.day_date,time:row.starts_at||'09:00',name:row.title,detail:row.place_name||`${trip.destination} · Idea to verify`,icon:'✦'}));}setSchedule(current=>[...current,...items]);notify(`Added ${items.length} AI-suggested ideas. Review details before you go.`);}catch(error){setDraftError(error instanceof Error?error.message:'Could not draft the itinerary.');}finally{setDraftingItinerary(false);}}
